from __future__ import annotations

import sqlite3

from fastapi import APIRouter, Depends, Query, status
from pydantic import BaseModel, Field

from app.config import Settings, get_settings
from app.db import get_db, utc_now
from app.errors import not_found
from app.pagination import PageParams, page_params, paginate
from app.security import CurrentUser, get_current_user

router = APIRouter(prefix="/api/todos", tags=["todos"])

class TodoCreate(BaseModel):
    title: str = Field(min_length=1, max_length=200)

class TodoUpdate(BaseModel):
    title: str | None = Field(default=None, min_length=1, max_length=200)
    done: bool | None = None

class TodoOut(BaseModel):
    id: int
    title: str
    done: bool
    created_at: str
    updated_at: str

class TodoList(BaseModel):
    items: list[TodoOut]
    total: int
    limit: int
    offset: int

@router.get("", response_model=TodoList, summary="List todos")
def list_todos(
    done: bool | None = Query(default=None, description="Filter by done status"),
    page: PageParams = Depends(page_params),
    current: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoList:
    sql = "SELECT id, title, done, created_at, updated_at FROM todos WHERE user_id = ?"
    params: list[object] = [current.id]
    if done is not None:
        sql += " AND done = ?"
        params.append(1 if done else 0)
    sql += " ORDER BY created_at DESC LIMIT ? OFFSET ?"
    params.extend([page.limit, page.offset])

    rows = conn.execute(sql, params).fetchall()
    items = [TodoOut(id=r["id"], title=r["title"], done=bool(r["done"]), created_at=r["created_at"], updated_at=r["updated_at"]) for r in rows]

    count_sql = "SELECT COUNT(*) FROM todos WHERE user_id = ?"
    count_params: list[object] = [current.id]
    if done is not None:
        count_sql += " AND done = ?"
        count_params.append(1 if done else 0)
    total = conn.execute(count_sql, count_params).fetchone()[0]

    return paginate(items, total, page)

@router.post("", response_model=TodoOut, status_code=status.HTTP_201_CREATED, summary="Create a todo")
def create_todo(
    data: TodoCreate,
    current: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
    now = utc_now()
    title = data.title.strip()
    cur = conn.execute(
        "INSERT INTO todos (user_id, title, done, created_at, updated_at) VALUES (?, ?, 0, ?, ?)",
        (current.id, title, now, now),
    )
    todo_id = cur.lastrowid
    return TodoOut(id=todo_id, title=title, done=False, created_at=now, updated_at=now)

def _get_todo(conn: sqlite3.Connection, todo_id: int, user_id: int) -> sqlite3.Row | None:
    return conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, user_id),
    ).fetchone()

@router.get("/{todo_id}", response_model=TodoOut, summary="Get a todo")
def get_todo(
    todo_id: int,
    current: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
    row = _get_todo(conn, todo_id, current.id)
    if not row:
        raise not_found("todo_not_found", "Todo not found.")
    return TodoOut(id=row["id"], title=row["title"], done=bool(row["done"]), created_at=row["created_at"], updated_at=row["updated_at"])

@router.patch("/{todo_id}", response_model=TodoOut, summary="Update a todo")
def update_todo(
    todo_id: int,
    data: TodoUpdate,
    current: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> TodoOut:
    row = _get_todo(conn, todo_id, current.id)
    if not row:
        raise not_found("todo_not_found", "Todo not found.")

    title = data.title.strip() if data.title is not None else row["title"]
    done = 1 if data.done else 0 if data.done is not None else row["done"]
    now = utc_now()

    conn.execute(
        "UPDATE todos SET title = ?, done = ?, updated_at = ? WHERE id = ?",
        (title, done, now, todo_id),
    )
    return TodoOut(id=todo_id, title=title, done=bool(done), created_at=row["created_at"], updated_at=now)

@router.delete("/{todo_id}", status_code=status.HTTP_204_NO_CONTENT, summary="Delete a todo")
def delete_todo(
    todo_id: int,
    current: CurrentUser = Depends(get_current_user),
    conn: sqlite3.Connection = Depends(get_db),
) -> None:
    row = _get_todo(conn, todo_id, current.id)
    if not row:
        raise not_found("todo_not_found", "Todo not found.")
    conn.execute("DELETE FROM todos WHERE id = ?", (todo_id,))
